// Prepare personalized email data
const lead = $input.item.json;
const fields = lead.fields || lead;

// Extract fields from Airtable record
const name = fields.Name || '';
const firstName = name.split(' ')[0] || name;
const title = fields.Title || '';
const company = fields.Company || '';
const industry = fields.Industry || '';
const aiScore = fields.AI_Score || 0;
const aiFitFactors = fields.AI_Fit_Factors || '';

// YOUR COMPANY INFO - Update these!
const myCompany = 'XCONS';
const myProduct = 'giải pháp tư vấn và triển khai công nghệ cho doanh nghiệp';
const myValueProp = 'giúp doanh nghiệp tối ưu quy trình vận hành và tăng trưởng doanh thu thông qua công nghệ';
const myName = 'Nhật';
const myTitle = 'Business Development';

const emailPrompt = `Hãy viết một email cold outreach chuyên nghiệp, cá nhân hoá bằng tiếng Việt.

Thông tin người nhận:
- Họ tên: ${name}
- Chức danh: ${title}
- Công ty: ${company}  
- Ngành: ${industry}

Thông tin người gửi:
- Công ty: ${myCompany}
- Sản phẩm/Dịch vụ: ${myProduct}
- Giá trị mang lại: ${myValueProp}
- Tên người gửi: ${myName}
- Chức danh người gửi: ${myTitle}

Yêu cầu email:
1. Mở đầu cá nhân hoá, thể hiện hiểu biết về ngành của họ
2. Nêu rõ 1 pain point cụ thể của ngành ${industry}
3. Giới thiệu giải pháp ngắn gọn, liên kết với pain point
4. Call to action rõ ràng: mời họ có 15 phút trao đổi
5. Giọng văn chuyên nghiệp nhưng thân thiện, không quá formal
6. Độ dài: 150-180 từ
7. Gọi họ bằng: ${firstName}

Trả về CHÍNH XÁC JSON sau (không có text khác):
{
  "subject": "<tiêu đề email hấp dẫn, dưới 60 ký tự>",
  "body": "<nội dung email đầy đủ, có xuống dòng \\n>",
  "preview_text": "<đoạn preview ngắn>"
}`;

return [{
  json: {
    record_id: lead.id,
    name,
    first_name: firstName,
    email: fields.Email,
    title,
    company,
    industry,
    linkedin_url: fields.LinkedIn_URL || '',
    ai_score: aiScore,
    emailPrompt
  }
}];

// Parse AI email response and prepare for sending
const leadData = $('Prepare Email Data').item.json;
const aiResponse = $input.item.json;

let emailContent = { subject: 'Giới thiệu giải pháp cho ' + leadData.company, body: 'Xin chào,\n\nTôi muốn giới thiệu giải pháp của chúng tôi...', preview_text: '' };

try {
  const content = aiResponse.choices?.[0]?.message?.content || '{}';
  emailContent = JSON.parse(content);
} catch (e) {
  console.error('Failed to parse AI email:', e);
}

// Convert \n to HTML line breaks
const htmlBody = emailContent.body
  .replace(/\n/g, '<br>')
  .replace(/\*\*(.*?)\*\*/g, '<strong>$1</strong>');

return [{
  json: {
    ...leadData,
    subject: emailContent.subject,
    body_plain: emailContent.body,
    body_html: `<div style="font-family: Arial, sans-serif; max-width: 600px; line-height: 1.6;">${htmlBody}</div>`,
    preview_text: emailContent.preview_text
  }
}];

// Extract Gmail message ID for thread tracking
const emailResult = $input.item.json;
const leadData = $('Parse Email Content').item.json;

const threadId = emailResult.threadId || emailResult.id || '';
const messageId = emailResult.id || '';

return [{
  json: {
    record_id: leadData.record_id,
    name: leadData.name,
    email: leadData.email,
    subject: leadData.subject,
    thread_id: threadId,
    message_id: messageId,
    sent_date: new Date().toISOString().split('T')[0]
  }
}];
